# Utility functions for reaction discovery.
def rxn_table(model, terms):
    rows=[]
    if isinstance(terms, str): terms=[terms]
    for r in model.reactions:
        text=(r.id+' '+(r.name or '')).lower()
        if any(t.lower() in text for t in terms):
            rows.append({'id':r.id,'name':r.name,'lower_bound':r.lower_bound,'upper_bound':r.upper_bound,'gene_rule':r.gene_reaction_rule})
    return pd.DataFrame(rows)

TARGETS = {
    'biomass': BIOMASS,
    'butyrate': 'EX_cpd00211_e0',
    'propionate': 'EX_cpd00141_e0',
    'acetate': 'EX_cpd00029_e0',
    'L_lactate': 'EX_cpd00159_e0',
    'D_lactate': 'EX_cpd00221_e0',
    'ammonia': 'EX_cpd00013_e0',
    'h2s': 'EX_cpd00239_e0',
    'methanethiol': 'EX_cpd00324_e0'
}
for k,v in TARGETS.items():
    print(f'{k:14s} {v:22s}', v in model.reactions)

for label, terms in {'butyrate':['butyrate','butyryl'], 'lactate':['lactate'], 'propionate':['propionate'], 'byproducts':['h2s','methanethiol','nh3','ammonia']}.items():
    df = rxn_table(model, terms)
    df.to_csv(TAB/f'reaction_candidates_{label}.csv', index=False)
    display(df.head(30))

def run_design(label, module, extra_modules=None, approach=None):
    extra_modules = extra_modules or []
    approach = approach or sd.BEST
    print('\n===', label, '===')
    sols = sd.compute_strain_designs(
        wt,
        sd_modules=[module] + extra_modules,
        max_solutions=MAX_SOLUTIONS,
        max_cost=MAX_COST,
        ko_cost=target_ko_cost,
        solution_approach=approach,
        time_limit=TIME_LIMIT,
        solver=str(cobra.Configuration().solver)
    )
    return sols

design_results = {}
if RUN_HEAVY:
    logging.basicConfig(level=logging.INFO)
    # Start with ANY for feasibility, then use BEST for final manuscript results.
    for label in ['optknock', 'tilted_optknock', 'robustknock', 'optcouple']:
        try:
            design_results[label] = run_design(label, modules[label], approach=sd.BEST)
        except Exception as e:
            print(label, 'failed:', repr(e))

    # Optional combined designs after base runs succeed.
    try:
        design_results['tilted_optknock_mcs_byproducts'] = run_design('tilted_optknock + MCS byproduct suppress', modules['tilted_optknock'], extra_modules=suppress_modules, approach=sd.BEST)
    except Exception as e:
        print('combined module failed:', repr(e))
else:
    print('RUN_HEAVY is False. Set RUN_HEAVY=True for local StrainDesign MILP execution.')

def apply_reaction_knockouts(model, knockout_ids):
    m = model.copy()
    for rid in knockout_ids:
        if rid in m.reactions:
            m.reactions.get_by_id(rid).bounds = (0, 0)
    return m

def phenotype_for_knockouts(model, knockout_ids):
    m = apply_reaction_knockouts(model, knockout_ids)
    m.objective = BIOMASS
    growth = m.slim_optimize()
    try:
        p = pfba(m)
        fluxes = p.fluxes
    except Exception:
        sol = m.optimize()
        fluxes = sol.fluxes
    out = {'growth': growth, 'n_knockouts': len(knockout_ids)}
    for k, rid in TARGETS.items():
        if rid in m.reactions:
            out[k] = float(fluxes.get(rid, np.nan))
    return out

# Evaluate all actual designs if available.
phenos=[]
if not interventions.empty:
    for (label, idx), grp in interventions.groupby(['design_type','solution_index']):
        kos = list(grp.loc[grp['intervention']=='knockout','reaction'])
        row = {'design_type': label, 'solution_index': idx, 'knockouts': ';'.join(kos)}
        row.update(phenotype_for_knockouts(wt, kos))
        phenos.append(row)
phenos = pd.DataFrame(phenos)
phenos.to_csv(TAB/'straindesign_solution_phenotypes.csv', index=False)
display(phenos)

if not phenos.empty:
    plt.figure(figsize=(7,5), dpi=160)
    plt.scatter(phenos['growth'], phenos['butyrate'], s=80)
    for _, r in phenos.iterrows():
        plt.text(r['growth'], r['butyrate'], f"{r['design_type']}:{int(r['solution_index'])}", fontsize=7)
    plt.xlabel('Predicted growth rate (h$^{-1}$)')
    plt.ylabel('Butyrate exchange flux')
    plt.title('StrainDesign candidate phenotypes')
    plt.tight_layout()
    plt.savefig(FIG/'straindesign_candidate_phenotypes.png', dpi=600)
    plt.savefig(FIG/'straindesign_candidate_phenotypes.svg')
    plt.show()
